n.a='\n## \ud83d\udee0\ufe0f \u53ef\u7528\u5de5\u5177\u5217\u8868\n\n### \u26a0\ufe0f \u91cd\u8981\u63d0\u793a\n\n\u4f5c\u4e3a AI \u52a9\u624b\uff0c\u4f60**\u65e0\u6cd5\u76f4\u63a5\u83b7\u53d6**\u4ee5\u4e0b\u7c7b\u578b\u7684\u4fe1\u606f\uff1a\n1. **\u5f53\u524d\u65f6\u95f4**\uff1a\u4f60\u65e0\u6cd5\u611f\u77e5\u65f6\u95f4\u6d41\u901d\uff0c**\u7edd\u5bf9\u7981\u6b62**\u786c\u7f16\u7801\u65e5\u671f\u65f6\u95f4\u5b57\u7b26\u4e32\uff08\u5982 "2025-01-15"\u3001"\u4eca\u5929\u662f1\u670815\u65e5"\uff09\n2. **\u7528\u6237\u6570\u636e**\uff1a\u6240\u6709\u7528\u6237\u7684\u4efb\u52a1\u3001\u7b14\u8bb0\u3001\u65e5\u8bb0\u7b49\u6570\u636e\u90fd\u5b58\u50a8\u5728\u672c\u5730\uff0c\u5fc5\u987b\u4f7f\u7528\u63d2\u4ef6\u5de5\u5177\u83b7\u53d6\n\n### \ud83d\udeab \u4e25\u683c\u7981\u6b62\u7684\u884c\u4e3a\n1. **\u7981\u6b62\u786c\u7f16\u7801\u65e5\u671f\u65f6\u95f4**\uff1a\n   - \u274c \u9519\u8bef\uff1a`const date = "2025-01-15"` \u6216 `const content = "\u4eca\u5929\u662f2025\u5e741\u670815\u65e5"`\n   - \u2705 \u6b63\u786e\uff1a`const date = await Aboutme.system.getCustomDate({format: "yyyy-MM-dd"})`\n'
n.a='\n## \ud83d\udee0\ufe0f \u53ef\u7528\u5de5\u5177\u5217\u8868\n\n### \u26a0\ufe0f \u91cd\u8981\u63d0\u793a\n\n\u4f5c\u4e3a AI \u52a9\u624b\uff0c\u4f60**\u65e0\u6cd5\u76f4\u63a5\u83b7\u53d6**\u4ee5\u4e0b\u7c7b\u578b\u7684\u4fe1\u606f\uff1a\n1. **\u5f53\u524d\u65f6\u95f4**\uff1a\u4f60\u65e0\u6cd5\u611f\u77e5\u65f6\u95f4\u6d41\u901d\uff0c**\u7edd\u5bf9\u7981\u6b62**\u786c\u7f16\u7801\u65e5\u671f\u65f6\u95f4\u5b57\u7b26\u4e32\uff08\u5982 "2025-01-15"\u3001"\u4eca\u5929\u662f1\u670815\u65e5"\uff09\n2. **\u7528\u6237\u6570\u636e**\uff1a\u6240\u6709\u7528\u6237\u7684\u4efb\u52a1\u3001\u7b14\u8bb0\u3001\u65e5\u8bb0\u7b49\u6570\u636e\u90fd\u5b58\u50a8\u5728\u672c\u5730\uff0c\u5fc5\u987b\u4f7f\u7528\u63d2\u4ef6\u5de5\u5177\u83b7\u53d6\n\n### \ud83d\udeab \u4e25\u683c\u7981\u6b62\u7684\u884c\u4e3a\n1. **\u7981\u6b62\u786c\u7f16\u7801\u65e5\u671f\u65f6\u95f4**\uff1a\n   - \u274c \u9519\u8bef\uff1a`const date = "2025-01-15"` \u6216 `const content = "\u4eca\u5929\u662f2025\u5e741\u670815\u65e5"`\n   - \u2705 \u6b63\u786e\uff1a`const date = await Aboutme.system.getCustomDate({format: "yyyy-MM-dd"})`\n2. **\u7981\u6b62\u4f7f\u7528\u5360\u4f4d\u7b26\u53d8\u91cf**\uff1a\n'
n.a='\n## \ud83d\udee0\ufe0f \u53ef\u7528\u5de5\u5177\u5217\u8868\n\n### \u26a0\ufe0f \u91cd\u8981\u63d0\u793a\n\n\u4f5c\u4e3a AI \u52a9\u624b\uff0c\u4f60**\u65e0\u6cd5\u76f4\u63a5\u83b7\u53d6**\u4ee5\u4e0b\u7c7b\u578b\u7684\u4fe1\u606f\uff1a\n1. **\u5f53\u524d\u65f6\u95f4**\uff1a\u4f60\u65e0\u6cd5\u611f\u77e5\u65f6\u95f4\u6d41\u901d\uff0c**\u7edd\u5bf9\u7981\u6b62**\u786c\u7f16\u7801\u65e5\u671f\u65f6\u95f4\u5b57\u7b26\u4e32\uff08\u5982 "2025-01-15"\u3001"\u4eca\u5929\u662f1\u670815\u65e5"\uff09\n2. **\u7528\u6237\u6570\u636e**\uff1a\u6240\u6709\u7528\u6237\u7684\u4efb\u52a1\u3001\u7b14\u8bb0\u3001\u65e5\u8bb0\u7b49\u6570\u636e\u90fd\u5b58\u50a8\u5728\u672c\u5730\uff0c\u5fc5\u987b\u4f7f\u7528\u63d2\u4ef6\u5de5\u5177\u83b7\u53d6\n\n### \ud83d\udeab \u4e25\u683c\u7981\u6b62\u7684\u884c\u4e3a\n1. **\u7981\u6b62\u786c\u7f16\u7801\u65e5\u671f\u65f6\u95f4**\uff1a\n   - \u274c \u9519\u8bef\uff1a`const date = "2025-01-15"` \u6216 `const content = "\u4eca\u5929\u662f2025\u5e741\u670815\u65e5"`\n   - \u2705 \u6b63\u786e\uff1a`const date = await Aboutme.system.getCustomDate({format: "yyyy-MM-dd"})`\n2. **\u7981\u6b62\u4f7f\u7528\u5360\u4f4d\u7b26\u53d8\u91cf**\uff1a\n   - \u274c \u9519\u8bef\uff1a`const channelId = "your_channel_id"` \u6216 `accountId: "\u8bf7\u586b\u5165\u8d26\u6237ID"`\n'
n.a=u.pe
p=u.pe+'   - \u2705 \u793a\u4f8b\uff1a`const channels = await Aboutme.plugins.chat.getChannels(); const firstChannel = channels[0]; await Aboutme.plugins.chat.sendMessage({channelId: firstChannel.id, content: "\u6d88\u606f\u5185\u5bb9"})`\n'
n.a=p
p+="\n### \u7cfb\u7edf API\uff08\u5728 JavaScript \u4ee3\u7801\u4e2d\u76f4\u63a5\u8c03\u7528\uff09\n"
n.a=p
p+="\n\u5f53\u9700\u8981\u65f6\u95f4\u6216\u8bbe\u5907\u4fe1\u606f\u65f6\uff0c**\u5fc5\u987b\u5728 JavaScript \u4ee3\u7801\u4e2d\u8c03\u7528\u7cfb\u7edfAPI**\uff0c\u4e0d\u8981\u4f5c\u4e3a\u5355\u72ec\u7684\u6b65\u9aa4\uff1a\n"
n.a=p
p+="\n#### \ud83c\udf1f \u63a8\u8350\uff1agetCustomDate\uff08\u89e3\u51b3\u65f6\u533a\u95ee\u9898\uff09\n"
n.a=p
p+="- `await Aboutme.system.getCustomDate(options)` - **\u63a8\u8350\u4f7f\u7528**\uff0c\u4e00\u6b21\u8c03\u7528\u89e3\u51b3\u6240\u6709\u65e5\u671f\u9700\u6c42\n"
n.a=p
p+="  - **options \u53c2\u6570**\uff1a\n"
n.a=p
p+="    - `baseDate`: \u57fa\u51c6\u65e5\u671f\uff08\u65f6\u95f4\u6233\u6216ISO\u5b57\u7b26\u4e32\uff09\uff0c\u9ed8\u8ba4\u5f53\u524d\u65f6\u95f4\n"
n.a=p
p+='    - `timezone`: "local"\uff08\u9ed8\u8ba4\uff09\u6216 "UTC"\n'
n.a=p
p+="    - `add`: \u589e\u52a0\u65f6\u95f4 `{days, hours, minutes, seconds, milliseconds}`\n"
n.a=p
p+="    - `subtract`: \u51cf\u5c11\u65f6\u95f4 `{days, hours, minutes, seconds, milliseconds}`\n"
n.a=p
p+="    - `relativePosition`: \u76f8\u5bf9\u4f4d\u7f6e\uff0c\u53ef\u9009\u503c\uff1a\n"
n.a=p
p+="      - `startOfDay` / `endOfDay` - \u5f53\u5929\u51cc\u6668/\u7ed3\u675f\n"
n.a=p
p+="      - `startOfHour` / `endOfHour` - \u5c0f\u65f6\u5f00\u59cb/\u7ed3\u675f\n"
n.a=p
p+="      - `startOfMonth` / `endOfMonth` - \u6708\u521d/\u6708\u672b\n"
n.a=p
p+="      - `startOfWeek` / `endOfWeek` - \u5468\u4e00/\u5468\u65e5\n"
n.a=p
p+="      - `startOfYear` / `endOfYear` - \u5e74\u521d/\u5e74\u672b\n"
n.a=p
p+="    - `format`: \u8fd4\u56de\u683c\u5f0f\n"
n.a=p
p+='      - `"object"`\uff08\u9ed8\u8ba4\uff09: \u8fd4\u56de\u5b8c\u6574\u5bf9\u8c61 `{timestamp, datetime, year, month, day, ...}`\n'
n.a=p
p+='      - `"timestamp"`: \u4ec5\u8fd4\u56de\u65f6\u95f4\u6233\n'
n.a=p
p+='      - `"iso"`: \u8fd4\u56de ISO 8601 \u5b57\u7b26\u4e32\n'
n.a=p
p+='      - `"text"`: \u8fd4\u56de\u76f8\u5bf9\u65f6\u95f4\uff08\u5982"3\u5929\u524d"\uff09\n'
n.a=p
p+='      - \u81ea\u5b9a\u4e49\u683c\u5f0f\u5982 `"yyyy-MM-dd HH:mm:ss"`\n'
n.a=p
p+="\n  **\u4f7f\u7528\u793a\u4f8b**\uff1a\n"
n.a=p
p+="  ```javascript\n"
n.a=p
p+="  // \u83b7\u53d6\u4eca\u5929\u51cc\u6668\uff08\u89e3\u51b3\u65f6\u533a\u95ee\u9898\uff09\n"
n.a=p
p+='  const todayStart = await Aboutme.system.getCustomDate({relativePosition: "startOfDay"});\n'
n.a=p
p+="  \n"
n.a=p
p+="  // \u83b7\u53d6\u660e\u5929\u51cc\u6668\u7684\u65f6\u95f4\u6233\n"
n.a=p
p+="  const tomorrowStart = await Aboutme.system.getCustomDate({\n"
n.a=p
p+="    add: {days: 1},\n"
n.a=p
p+='    relativePosition: "startOfDay",\n'
n.a=p
p+='    format: "timestamp"\n'
n.a=p
p+="  });\n"
n.a=p
p+="  \n"
n.a=p
p+="  // \u83b7\u53d6\u672c\u5468\u4e00\u51cc\u6668\n"
n.a=p
p+='  const weekStart = await Aboutme.system.getCustomDate({relativePosition: "startOfWeek"});\n'
n.a=p
p+="  \n"
n.a=p
p+="  // \u83b7\u53d63\u5929\u524d\u7684\u65e5\u671f\uff0c\u683c\u5f0f\u5316\u8f93\u51fa\n"
n.a=p
p+="  const threeDaysAgo = await Aboutme.system.getCustomDate({\n"
n.a=p
p+="    subtract: {days: 3},\n"
n.a=p
p+='    format: "yyyy-MM-dd"\n'
n.a=p
p+="  });\n"
n.a=p
p+="  ```\n"
n.a=p
p+="\n#### \u5176\u4ed6\u65f6\u95f4 API\n"
n.a=p
p+="- `await Aboutme.system.getCurrentTime()` - \u83b7\u53d6\u5f53\u524d\u65f6\u95f4\uff0c\u8fd4\u56de `{timestamp, datetime, year, month, day, hour, minute, second, weekday, weekdayName}`\n"
n.a=p
p+=u.vW
n.a=p
p+=u.po
n.a=p
p+="\n#### \u8bbe\u5907\u4e0e\u5e94\u7528\u4fe1\u606f\n"
n.a=p
p+=u.eZ
n.a=p
p+="- `await Aboutme.system.getAppInfo()` - \u83b7\u53d6\u5e94\u7528\u4fe1\u606f\n"
n.a=p
p+="\n### \u6b65\u9aa4\u95f4\u7ed3\u679c\u4f20\u9012 API\uff08\u591a\u6b65\u9aa4\u534f\u4f5c\uff09\n\n"
n.a=p
p+="\u5f53\u5de5\u5177\u8c03\u7528\u5305\u542b\u591a\u4e2a\u6b65\u9aa4\u65f6\uff0c\u53ef\u4ee5\u4f7f\u7528\u4ee5\u4e0b API \u5728\u6b65\u9aa4\u4e4b\u95f4\u4f20\u9012\u6570\u636e\uff1a\n\n"
n.a=p
p+="#### \u26a0\ufe0f \u5f3a\u5236\u8981\u6c42\uff1a\u5fc5\u987b\u4f7f\u7528\u5bf9\u8c61\u7c7b\u578b\n\n"
n.a=p
p+=u.eu
n.a=p
p+=u.n6
n.a=p
p+="#### API \u8bf4\u660e\n\n"
n.a=p
p+="- `await Aboutme.toolCall.setResult({id?, value})` - \u4fdd\u5b58\u7ed3\u679c\u4f9b\u540e\u7eed\u6b65\u9aa4\u4f7f\u7528\n"
n.a=p
p+='  - `id` (\u53ef\u9009): \u81ea\u5b9a\u4e49\u7ed3\u679c ID\uff0c\u5982 "userData"\u3001"taskList"\n'
n.a=p
p+="  - `value` (\u5fc5\u9700): **\u5fc5\u987b\u662f\u5bf9\u8c61** `{key: value}`\uff0c\u4e0d\u80fd\u662f\u6570\u7ec4\u6216\u539f\u59cb\u503c\n"
n.a=p
p+="- `await Aboutme.toolCall.getResult({id?, step?, default?})` - \u83b7\u53d6\u4e4b\u524d\u6b65\u9aa4\u7684\u7ed3\u679c\n"
n.a=p
p+="  - `id` (\u53ef\u9009): \u7ed3\u679c ID\n"
n.a=p
p+="  - `step` (\u53ef\u9009): \u6b65\u9aa4\u7d22\u5f15\uff08\u4ece 0 \u5f00\u59cb\uff09\uff0c\u5982 `{step: 0}` \u83b7\u53d6\u7b2c\u4e00\u4e2a\u6b65\u9aa4\u7684\u7ed3\u679c\n"
n.a=p
p+="  - `default` (\u53ef\u9009): \u9ed8\u8ba4\u503c\uff0c\u7ed3\u679c\u4e0d\u5b58\u5728\u65f6\u8fd4\u56de\n"
n.a=p
p+="  - **\u8fd4\u56de\u503c**: \u6c38\u8fdc\u662f\u5bf9\u8c61\u7c7b\u578b\uff0c\u901a\u8fc7 `result.propertyName` \u8bbf\u95ee\u6570\u636e\n"
n.a=p
p+="\n**\u81ea\u52a8\u4fdd\u5b58**\uff1a\u6bcf\u4e2a\u6b65\u9aa4\u6267\u884c\u6210\u529f\u540e\uff0c\u7ed3\u679c\u4f1a\u81ea\u52a8\u4fdd\u5b58\u5230 `step_N`\uff08N \u4e3a\u6b65\u9aa4\u7d22\u5f15\uff09\n"
n.a=p
p+="\n**\ud83d\udeab \u9519\u8bef\u793a\u4f8b\uff08\u7981\u6b62\uff09**:\n"
n.a=p
p+="```javascript\n"
n.a=p
p+="// \u274c \u9519\u8bef\uff1asetResult \u4f20\u5165\u6570\u7ec4\n"
n.a=p
p+=u.nG
n.a=p
p+="await Aboutme.toolCall.setResult({value: tasks}); // \u9519\u8bef\uff01tasks \u662f\u6570\u7ec4\n"
n.a=p
p+="\n"
n.a=p
p+="// \u274c \u9519\u8bef\uff1agetResult \u5f53\u4f5c\u6570\u7ec4\u4f7f\u7528\n"
n.a=p
p+="const tasks = await Aboutme.toolCall.getResult({step: 0});\n"
n.a=p
p+=u.ag
n.a=p
p+="```\n\n"
n.a=p
p+="**\u2705 \u6b63\u786e\u793a\u4f8b\uff08\u5fc5\u987b\u9075\u5faa\uff09**:\n"
n.a=p
p+="```javascript\n"
n.a=p
p+="// \u2705 \u6b63\u786e\uff1asetResult \u4f20\u5165\u5bf9\u8c61\uff0c\u7528\u5c5e\u6027\u5305\u88c5\u6570\u636e\n"
n.a=p
p+=u.nG
n.a=p
p+="await Aboutme.toolCall.setResult({value: {tasks, count: tasks.length}}); // \u6b63\u786e\uff01\n"
n.a=p
p+="\n"
n.a=p
p+="// \u2705 \u6b63\u786e\uff1agetResult \u8fd4\u56de\u5bf9\u8c61\uff0c\u901a\u8fc7\u5c5e\u6027\u8bbf\u95ee\n"
n.a=p
p+="const result = await Aboutme.toolCall.getResult({step: 0});\n"
n.a=p
p+=u.BR
n.a=p
p+="```\n"
n.a=p
p+="\n\u4f18\u5148\u4f7f\u7528\u4e0a\u9762\u5217\u51fa\u7684\u4e13\u7528\u63d2\u4ef6\u5de5\u5177\u3002\u53ea\u6709\u6ca1\u6709\u5408\u9002\u5de5\u5177\uff0c\u6216\u786e\u5b9e\u9700\u8981\u7528\u811a\u672c\u7ec4\u5408\u64cd\u4f5c\u65f6\uff0c\u624d\u751f\u6210 JavaScript \u6b65\u9aa4\u3002\n"
n.a=p
p+="\n## \ud83d\udcdd \u5de5\u5177\u8c03\u7528\u683c\u5f0f\n\n"
n.a=p
p+="**\ud83d\udea8 \u91cd\u8981\uff1a\u5fc5\u987b\u4f7f\u7528\u4ee5\u4e0b Markdown \u683c\u5f0f\uff0c\u4e0d\u8981\u4f7f\u7528 JSON \u683c\u5f0f\uff01**\n\n"
n.a=p
p+="**\u4e25\u683c\u9075\u5faa**:\n"
n.a=p
p+="1. **\u4ec5\u8fd4\u56de** \u4ee5\u4e0b\u683c\u5f0f\u7684\u5de5\u5177\u8c03\u7528\n"
n.a=p
p+="2. **\u4e0d\u8981** \u4efb\u4f55\u989d\u5916\u6587\u672c\u6216\u89e3\u91ca\n"
n.a=p
p+='3. **\u4e0d\u8981** \u4f7f\u7528 JSON \u683c\u5f0f\uff08\u5982 `{"steps": [...]}`\uff09\n'
n.a=p
p+="4. **\u4e0d\u8981** \u5728\u5916\u5c42\u5305\u88f9 ` ```markdown ` \u4ee3\u7801\u5757\n"
n.a=p
p+="5. **\u5fc5\u987b** \u4f7f\u7528\u4ee5\u4e0b\u683c\u5f0f\uff1a\n\n"
n.a=p
p+="```\n\n"
n.a=p
p+="# \u6b65\u9aa4\u6807\u9898\n"
n.a=p
p+="## \u6b65\u9aa4\u63cf\u8ff0\uff08\u53ef\u9009\uff09\n"
n.a=p
p+="```javascript\n"
n.a=p
p+="// JavaScript \u4ee3\u7801\n"
n.a=p
p+="```\n"
n.a=p
p+="```\n\n"
n.a=p
p=n.a=p+A.jX0()
o=A.aR($.vA().b,t.N,t.hR)
if(o.a!==0){n.a=p+"### \ud83d\udcda \u53ef\u7528\u5de5\u5177\n\n"
o.bz(0,new A.eYe(n))}else n.a=p+"\uff08\u6682\u65e0\u53ef\u7528\u5de5\u5177\uff09\n\n"
p=(n.a+="### \ud83d\udca1 \u4f7f\u7528\u793a\u4f8b\n\n")+"**\u793a\u4f8b 1\uff1a\u67e5\u8be2\u4eca\u5929\u7684\u4efb\u52a1**\n\n"
n.a=p
p+="```\n\n"
n.a=p
p+="# \u83b7\u53d6\u4eca\u65e5\u4efb\u52a1\n"
n.a=p
p+="\u67e5\u8be2\u4eca\u5929\u7684\u6240\u6709\u5f85\u529e\u4efb\u52a1\n"
n.a=p
p+="```javascript\n"
n.a=p
p+="const today = await Aboutme.system.getCustomDate(); const tasks = await Aboutme.plugins.todo.getTodayTasks(); const result = `\u4eca\u5929\u662f${today.month}\u6708${today.day}\u65e5\uff0c\u6709 ${tasks.length} \u4e2a\u4efb\u52a1`; setResult(result); return result;\n"
n.a=p
p+="```\n"
n.a=p
p+="```\n\n"
n.a=p
p+="**\u793a\u4f8b 2\uff1a\u67e5\u8be2\u5e76\u5904\u7406\u6570\u636e**\n\n"
n.a=p
p+="```\n\n"
n.a=p
p+="# \u7edf\u8ba1\u4efb\u52a1\u60c5\u51b5\n"
n.a=p
p+="\u83b7\u53d6\u5e76\u7edf\u8ba1\u4eca\u65e5\u4efb\u52a1\n"
n.a=p
p+="```javascript\n"
n.a=p
p+="const tasks = await Aboutme.plugins.todo.getTodayTasks(); const result = { total: tasks.length, completed: tasks.filter(t => t.completed).length }; setResult(result); return result;\n"
n.a=p
p+="```\n"
n.a=p
p+="```\n\n"
n.a=p
p+="**\u793a\u4f8b 3\uff1a\u5b8c\u6574\u7684\u7b7e\u5230\u6d41\u7a0b\uff08\u67e5\u8be2+\u6267\u884c\uff09**\n\n"
n.a=p
p+='\u7528\u6237\u8bf7\u6c42"\u5e2e\u6211\u5b8c\u6210\u7b7e\u5230"\u65f6\uff0c\u5e94\u8be5\u76f4\u63a5\u6267\u884c\u5b8c\u6574\u6d41\u7a0b\uff1a\n\n'
n.a=p
p+="```\n\n"
n.a=p
p+="# \u6267\u884c\u7b7e\u5230\u64cd\u4f5c\n"
n.a=p
p+="\u67e5\u627e\u7b2c\u4e00\u4e2a\u672a\u7b7e\u5230\u7684\u9879\u76ee\u5e76\u6267\u884c\u7b7e\u5230\n"
n.a=p
p+="```javascript\n"
n.a=p
p+="const items = await Aboutme.plugins.checkin.getCheckinItems(); const target = items.find(i => !i.isCheckedToday); if (!target) { const msg = '\u6240\u6709\u9879\u76ee\u4eca\u5929\u90fd\u5df2\u7b7e\u5230'; setResult(msg); return msg; } const result = await Aboutme.plugins.checkin.checkin(target.id); const msg = result.success ? `\u7b7e\u5230\u6210\u529f: ${target.name}` : result.message; setResult(msg); return msg;\n"
n.a=p
p+="```\n"
n.a=p
p+="```\n\n"
n.a=p
p+="**\u793a\u4f8b 4\uff1a\u6b65\u9aa4\u95f4\u6570\u636e\u4f20\u9012\uff08\u67e5\u8be2\u2192\u5206\u6790\u2192\u751f\u6210\u62a5\u544a\uff09**\n\n"
n.a=p
p+="\u4f7f\u7528 setResult/getResult \u5728\u6b65\u9aa4\u4e4b\u95f4\u4f20\u9012\u6570\u636e\uff08\u26a0\ufe0f \u5fc5\u987b\u4f7f\u7528\u5bf9\u8c61\u7c7b\u578b\uff09\uff1a\n\n"
n.a=p
p+="```\n\n"
n.a=p
p+="# \u67e5\u8be2\u4eca\u65e5\u4efb\u52a1\n"
n.a=p
p+="\u83b7\u53d6\u4eca\u5929\u7684\u4efb\u52a1\u5217\u8868\n"
n.a=p
p+="```javascript\n"
n.a=p
p+="const tasks = await Aboutme.plugins.todo.getTodayTasks(); await Aboutme.toolCall.setResult({id: 'todayTasks', value: {tasks, count: tasks.length}}); return `\u5df2\u83b7\u53d6 ${tasks.length} \u4e2a\u4efb\u52a1`;\n"
n.a=p
p+="```\n"
n.a=p
p+="\n"
n.a=p
p+="# \u7edf\u8ba1\u4efb\u52a1\u60c5\u51b5\n"
n.a=p
p+="\u5206\u6790\u4efb\u52a1\u5b8c\u6210\u60c5\u51b5\n"
n.a=p
p+="```javascript\n"
n.a=p
p+="const result = await Aboutme.toolCall.getResult({id: 'todayTasks'}); const tasks = result.tasks; const completed = tasks.filter(t => t.completed).length; const rate = (completed / tasks.length * 100).toFixed(1); return `\u5b8c\u6210\u7387: ${rate}%`;\n"
n.a=p
p+="```\n"
n.a=p
p+="```\n\n"
n.a=p
p+="**\u793a\u4f8b 5\uff1a\u591a\u6b65\u9aa4\u64cd\u4f5c\u94fe\uff08\u67e5\u8be2\u6761\u4ef6+\u521b\u5efa\uff09**\n\n"
n.a=p
p+='\u5f53\u7528\u6237\u8bf4"\u521b\u5efa\u660e\u5929\u7684\u4efb\u52a1"\u65f6\uff0c\u76f4\u63a5\u5b8c\u6210\u521b\u5efa\uff1a\n\n'
n.a=p
p+="```\n\n"
n.a=p
p+="# \u521b\u5efa\u660e\u5929\u7684\u4efb\u52a1\n"
n.a=p
p+="\u83b7\u53d6\u660e\u5929\u65e5\u671f\u5e76\u521b\u5efa\u4efb\u52a1\n"
n.a=p
p+="```javascript\n"
n.a=p
p+="const tomorrow = await Aboutme.system.getCustomDate({add: {days: 1}, relativePosition: 'startOfDay', format: 'timestamp'}); const result = await Aboutme.plugins.todo.createTask('New Task', { dueDate: tomorrow }); const msg = result.success ? 'Task created successfully' : 'Failed to create task'; setResult(msg); return msg;\n"
n.a=p
p+="```\n"
n.a=p
p+="```\n\n"
n.a=p
p+="### \u26a0\ufe0f \u6ce8\u610f\u4e8b\u9879\n\n"
n.a=p
p+="1. **\ud83d\udeab \u7edd\u5bf9\u7981\u6b62\u786c\u7f16\u7801\u65e5\u671f\u65f6\u95f4**\uff1a\u4efb\u4f55\u6d89\u53ca\u65e5\u671f\u65f6\u95f4\u7684\u4ee3\u7801\uff0c\u63a8\u8350\u4f7f\u7528 `await Aboutme.system.getCustomDate(options)` \u83b7\u53d6\u548c\u5904\u7406\u65f6\u95f4\n"
n.a=p
p+="   - \u751f\u6210\u65e5\u8bb0\u5185\u5bb9\u65f6\uff0c\u4f7f\u7528\u7cfb\u7edfAPI\u83b7\u53d6\u7684\u771f\u5b9e\u65e5\u671f\uff0c\u4e0d\u8981\u4f7f\u7528\u4f60\u77e5\u8bc6\u4e2d\u7684\u65e5\u671f\n"
n.a=p
p+="   - \u521b\u5efa\u4efb\u52a1\u3001\u8d26\u5355\u7b49\u9700\u8981\u65e5\u671f\u7684\u64cd\u4f5c\uff0c\u90fd\u5fc5\u987b\u5148\u8c03\u7528\u7cfb\u7edfAPI\n"
n.a=p
p+='2. **\ud83d\udeab \u7edd\u5bf9\u7981\u6b62\u4f7f\u7528\u5360\u4f4d\u7b26**\uff1a\u4e0d\u5141\u8bb8\u4f7f\u7528 "your_xxx_id"\u3001"\u8bf7\u586b\u5165xxx" \u7b49\u5360\u4f4d\u7b26\n'
n.a=p
p+="   - \u5982\u679c\u7528\u6237\u672a\u6307\u5b9aID\uff0c\u4f18\u5148\u904d\u5386\u5df2\u6709\u6570\u636e\u9009\u62e9\u5408\u9002\u7684\uff08\u7b2c\u4e00\u4e2a\u3001\u6700\u8fd1\u7684\u3001\u7b26\u5408\u6761\u4ef6\u7684\uff09\n"
n.a=p
